INSERT INTO clinic_faqs (id, question, answer, position, active) VALUES
  (1, 'What if I am running late?', 'Come anyway and speak to the desk. If you are more than {no_show_minutes} minutes past your start we may have to move you to the next open time, but we will always try to fit you in.', 0, TRUE),
  (2, 'How do I change or cancel?', 'From My visits, or ring the desk on {phone}. There is no charge until {cancel_hours} hours before the start. Inside that we still will not charge you, but the time is hard to give to somebody else — so tell us as soon as you know.', 1, TRUE),
  (3, 'What should I bring?', 'Your mobile, so you have the reference, and anything the desk asked for when you booked. If you told us something in the note, it is already on the day sheet.', 2, TRUE),
  (4, 'Can I book for somebody else?', 'Yes. Book it in their name and add a line for the desk so we know who is coming with them.', 3, TRUE),
  (5, 'How long will I wait once I am there?', 'The board at the desk shows how long each person has been in the building. Most people are seen within ten minutes of their start; if it slips past twenty, ask us and we will find out where things are.', 4, TRUE),
  (6, 'Do you see children?', 'Yes, from birth upwards. Bring an adult who can stay for the whole visit.', 5, TRUE);
